// Define the function pointer type for the integrand
typedef double (*FunctionPtr)(double);

// Simpson's rule for a single interval [a,b]
auto simpson_rule = [](FunctionPtr f, double a, double b) -> double {
    return (b - a) / 6.0 * (f(a) + 4.0 * f((a + b) / 2.0) + f(b));
};

// Recursive helper function for adaptive Simpson's method
std::function<double(double, double, double)> adaptive_simpson_helper;

// Maximum recursion depth to prevent stack overflow
const int max_depth = 100;

auto simpson_integrate = [&](FunctionPtr f, double a, double b, double eps, int depth) -> double {
    if (depth >= max_depth) {
        return simpson_rule(f, a, b); // Base case: max depth reached
    }

    double c = (a + b) / 2.0;
    double whole = simpson_rule(f, a, b);
    double left = simpson_rule(f, a, c);
    double right = simpson_rule(f, c, b);
    double lr_sum = left + right;

    // If the error is small enough, return the estimate
    if (std::abs(whole - lr_sum) < 15 * eps) { // 15 for error bound adjustment
        return lr_sum;
    } else {
        // Otherwise, recurse on the left and right subintervals
        double eps_over_2 = eps / 2.0;
        double left_integral = adaptive_simpson_helper(f, a, c, eps_over_2, depth + 1);
        double right_integral = adaptive_simpson_helper(f, c, b, eps_over_2, depth + 1);
        return left_integral + right_integral;
    }
};

// Assign the lambda to the function pointer for recursive calls
